      var step = 0;
      var value = 0;

      switch (encoding) {
        case encodingVarint:
          value = _asByte(readOptimalInt32(), fieldName);
          break;

        case encodingDelta:
          step = readOptimalInt32();
          break;

        case encodingRle:
          run = readCounter32();
          value = _asByte(readOptimalInt32(), fieldName);
          break;

        default: // encodingDeltaRle
          run = readCounter32();
          step = readOptimalInt32();
          break;
      }

      if (run < 1 || run > count - filled) {
        throw TcbException(
            '$fieldName: a run of $run cannot cover the ${count - filled} bytes left');
      }

      for (var at = 0; at < run; at++) {
        if (walking) {
          previous = _asByte((previous + step).toSigned(32), fieldName);
          out[filled++] = previous;
        } else {
          out[filled++] = value;
        }
      }
    }

    return out;
  }

  /// A decoded value that has to be a byte, or the block is corrupt.
  static int _asByte(int value, String fieldName) {
    if (value < 0 || value > 255) {
      throw TcbException('$fieldName: $value is not a byte');
    }

    return value;
  }

  /// An enum value, which travels zig-zag encoded rather than fixed width.
  int readEnum() => readOptimalInt32();

  int _readVarint32() {
    var value = 0;

    // Multiplied and added rather than shifted and ored: both of those are 32-bit on the
    // web, and the fifth byte of a varint lands past that.
    var scale = 1;

    for (var step = 0; step < 5; step++) {
      final b = readUint8();

      value += (b & 0x7F) * scale;

      if (b & 0x80 == 0) return value;

      scale *= 128;
    }

    throw TcbException('varint32 is longer than five bytes');
  }
}

/// Reads one scalar column's values in row order, whatever the block's encoding.
///
/// The generated row loop stays a row loop; this is the one place that knows how a
/// delta accumulates, how long a run has left, or that a dictionary index is a
/// reference into strings decoded once. That last one matters beyond file size: a
/// hundred-thousand-row column with three distinct strings allocates three strings,
/// not a hundred thousand.
///
/// checkColumn has already refused any (element, encoding) pair the spec does not
/// define, so the switches here do not re-litigate that.
