    // differ in length, one for the lengths. Both are encodings that already exist, so all
    // this does is read them and then go on being the element stream's cursor.
    if (_encoding == encodingArray) {
      _encoding = _reader.readUint8();

      if (column.kind == kindArray) {
        final lengthEncoding = _reader.readUint8();
        final lengths = _readLengths(_reader, lengthEncoding, rowCount, _fieldName);

        var elements = 0;

        for (final length in lengths) {
          elements += length;
        }

        if (elements > 0x7FFFFFFF) {
          throw TcbException(
              '$_fieldName: the column declares more elements than can be held');
        }

        _lengths = lengths;
        _rowsRemaining = elements;
      }
    }

    // A bit-packed column states the width its range needs, the base subtracted from
    // every value, and which encoding carries the packed bytes. Decoded here so that
    // handing values out is a shift and an add.
    if (_encoding == encodingBitpack) {
      final width = _reader.readUint8();
      final base = _reader.readCounter64();
      final inner = _reader.readUint8();

      if (width < 1 || width > 64) {
        throw TcbException('$_fieldName: a bit width of $width is not between 1 and 64');
      }

      _packedWidth = width;
      _packedBase = base;
      _packed = _reader.readByteStream(
          inner, (_rowsRemaining * width + 7) ~/ 8, _fieldName);

      return;
    }

    // A float column whose values are all whole numbers carries them as integers and says
    // which integer encoding they travel under. From here down it is that encoding's
    // cursor, and only the handing out converts back.
    if (_encoding == encodingWhole) {
      final inner = _reader.readUint8();

      if (inner < encodingVarint || inner > encodingDeltaRle) {
        throw TcbException(
            "$_fieldName: encoding $inner cannot carry a whole-number column's values");
      }

      _encoding = inner;
      _wholeNumbers = true;
    }

    // A segment dictionary is built once, here, and from then on the block is a dictionary
    // with an index stream like any other - so the row-by-row paths below need to know
    // nothing about it.
    if (_encoding == encodingDictSegment || _encoding == encodingDictSegmentRle) {
      _dictionary = _readSegmentDictionary(_reader, _fieldName);

      _encoding = _encoding == encodingDictSegment ? encodingDict : encodingDictRle;
      return;
    }

    final plainDictionary = _encoding == encodingDict || _encoding == encodingDictRle;

    final frontDictionary =
        _encoding == encodingDictFront || _encoding == encodingDictFrontRle;

    if (!plainDictionary && !frontDictionary) return;

    final count = _reader.readCounter32();

    if (count < 0) {
      throw TcbException('$_fieldName: the dictionary entry count is negative');
    }

    if (frontDictionary) {
      _dictionary = _readFrontCodedDictionary(_reader, count, _fieldName);
      return;
    }

    if (_element == elementString) {
      _dictionary = List<String>.generate(count, (_) => _reader.readString());
      return;
    }

    // A fixed-width element: the entries are the value's own bytes, so they are taken
    // as bytes and turned into values only when a row asks for one.
    _valueWidth = _element == elementF32 ? 4 : 8;

    final entries = Uint8List(count * _valueWidth);
    _reader.readBytesInto(entries, 0, entries.length);

    _valueDictionary = ByteData.view(entries.buffer);
