  /// byte boundary, so handing values out one at a time would mean carrying a decoder and
  /// a bit offset that disagree about where they are.
  List<int>? _packed;
  int _packedWidth = 0;
  int _packedBase = 0;
  int _packedBit = 0;

  /// How many elements the next row of an array column holds.
  ///
  /// One call whichever way the block is laid out. An encoded array decoded every length
  /// before the first element was read, so this hands out what it already has; a raw one
  /// states each row's length in front of that row's elements, so this reads it where it
  /// stands.
  int nextLength() {
    final lengths = _lengths;

    if (lengths != null) {
      if (_lengthAt >= lengths.length) {
        throw TcbException('$_fieldName: the column has no more rows to read');
      }

      return lengths[_lengthAt++];
    }

    final length = _reader.readCounter32();

    if (length < 0) {
      throw TcbException('$_fieldName: a row declares $length elements');
    }

    return length;
  }

  /// The next int32 - which also serves enums, and reference indexes.
  /// The next value of a bit-packed stream: the packed bits, over the block's base.
  ///
  /// A value may cross a byte boundary, so this walks bits rather than bytes. Dart's int
  /// is 64 bits and wraps, which is the arithmetic the format asks for.
  int _nextPacked() {
    var slot = 0;
    final packed = _packed!;

    for (var at = 0; at < _packedWidth; at++, _packedBit++) {
      if (packed[_packedBit >> 3] >> (_packedBit & 7) & 1 != 0) {
        slot |= 1 << at;
      }
    }

    return _packedBase + slot;
  }

  int nextI32() {
    _rowsRemaining--;

    if (_encoding == encodingBitpack) return _nextPacked().toSigned(32);

    switch (_encoding) {
      case encodingRaw:
        return _element == elementI32 ? _reader.readInt32() : _reader.readOptimalInt32();

      case encodingVarint:
        return _reader.readOptimalInt32();

      case encodingDelta:
        // The addition wraps on purpose, mirroring the writer's wrapping subtraction;
        // together they are exact for every int32 pair.
        if (_started) {
          _previous = _wrap32(_previous + _reader.readOptimalInt32());
        } else {
          _previous = _reader.readOptimalInt32();
          _started = true;
        }

        return _previous;

      case encodingRle:
        if (_runRemaining == 0) _readRun();

        _runRemaining--;
        return _runValue;

      default: // encodingDeltaRle; checkColumn refused everything else.
        if (!_started) {
          _previous = _reader.readOptimalInt32();
          _started = true;
          return _previous;
        }

        if (_runRemaining == 0) _readRun();

        _runRemaining--;
        _previous = _wrap32(_previous + _runValue);
        return _previous;
    }
