    if (_encoding == encodingBitpack) {
      _rowsRemaining--;
      return BigInt.from(_nextPacked());
    }

    final dictionary = _valueDictionary;

    if (dictionary != null) {
      final at = _nextValueEntry();

      // Assembled from two 32-bit halves exactly as readInt64 does, so a dictionary
      // entry and a raw value of the same eight bytes come back the same BigInt.
      final low = BigInt.from(dictionary.getUint32(at, Endian.little));
      final high = BigInt.from(dictionary.getInt32(at + 4, Endian.little));

      return (high << 32) | low;
    }

    _rowsRemaining--;
    return _reader.readInt64();
  }

  /// A float member: raw, the dictionary entry's exact bit pattern, or a whole number -
  /// widened to a double in every case, as Dart has no single-precision type.
  double nextF32() {
    if (_wholeNumbers) return nextI32().toDouble();

    final dictionary = _valueDictionary;

    if (dictionary != null) {
      return dictionary.getFloat32(_nextValueEntry(), Endian.little);
    }

    _rowsRemaining--;
    return _reader.readFloat();
  }

  /// A double member: from f64 or f32 - either of them raw or dictionary-encoded - and
  /// from an i32 column by decoding and widening.
  double nextF64() {
    if (_wholeNumbers) return nextI32().toDouble();

    if (_element == elementF64) {
      final dictionary = _valueDictionary;

      if (dictionary != null) {
        return dictionary.getFloat64(_nextValueEntry(), Endian.little);
      }

      _rowsRemaining--;
      return _reader.readDouble();
    }

    if (_element == elementF32) return nextF32();

    return nextI32().toDouble();
  }

  /// A bool member: one byte raw, or a run of them.
  bool nextBool() {
    if (_encoding == encodingRle || _encoding == encodingBitpack) {
      return nextI32() != 0;
    }

    _rowsRemaining--;
    return _reader.readBool();
  }

  /// The byte offset of the next row's dictionary entry, for a fixed-width element.
  int _nextValueEntry() {
    _rowsRemaining--;

    int index;

    if (_encoding == encodingDict) {
      index = _reader.readCounter32();
    } else {
      if (_runRemaining == 0) _readRun();

      _runRemaining--;
      index = _runValue;
    }

    final dictionary = _valueDictionary!;
    final count = dictionary.lengthInBytes ~/ _valueWidth;

    if (index < 0 || index >= count) {
      throw TcbException(
          '$_fieldName: dictionary index $index is out of range - the '
          'dictionary holds $count entries');
    }

    return index * _valueWidth;
  }

  /// The next string - the dictionary's instance where the block has one.
  String nextString() {
    _rowsRemaining--;

    switch (_encoding) {
      case encodingRaw:
        return _reader.readString();

      case encodingDict:
      case encodingDictFront:
        return _dictionaryEntry(_reader.readCounter32());

      default: // encodingDictRle and encodingDictFrontRle
        if (_runRemaining == 0) _readRun();

        _runRemaining--;
        return _dictionaryEntry(_runValue);
    }
  }

  /// A sorted dictionary whose entries state only what they do not share with the entry
  /// before them.
  ///
  /// Decoded into whole strings here rather than kept folded, because a row wants a
  /// string and the folding was only ever about the bytes on disk. The scratch buffer
  /// grows to the longest entry and is reused, so the allocations are the strings
  /// themselves - one per distinct value, which is the point.
  static List<String> _readFrontCodedDictionary(
      TcbReader reader, int count, String fieldName) {
    final entries = List<String>.filled(count, '');

    var scratch = Uint8List(64);
    var previousLength = 0;

    for (var at = 0; at < count; at++) {
      final shared = reader.readCounter32();
      final rest = reader.readCounter32();

      if (shared < 0 || rest < 0 || shared > previousLength) {
        throw TcbException(
            '$fieldName: dictionary entry $at shares $shared bytes with an entry '
            'of $previousLength');
      }

      final length = shared + rest;

      if (length > scratch.length) {
        var capacity = scratch.length;

        while (capacity < length) {
          capacity *= 2;
        }

        final grown = Uint8List(capacity);
        grown.setRange(0, previousLength, scratch);
        scratch = grown;
      }

      if (rest > 0) reader.readBytesInto(scratch, shared, rest);

      entries[at] =
          length == 0 ? '' : utf8.decode(Uint8List.sublistView(scratch, 0, length));

      previousLength = length;
    }

    return entries;
  }

  /// The lengths of an array column's rows, as their own encoded stream.
  ///
  /// A varint stream, so what may be chosen for it is what may be chosen for any varint
  /// column - each length as a counter32, or runs of them. Most columns have rows that are
  /// all the same length, which is one run.
  static List<int> _readLengths(
      TcbReader reader, int encoding, int rowCount, String fieldName) {
    final lengths = List<int>.filled(rowCount, 0);

    if (encoding == encodingRaw) {
      for (var at = 0; at < rowCount; at++) {
        final length = reader.readCounter32();

        if (length < 0) {
          throw TcbException('$fieldName: row $at declares $length elements');
        }

        lengths[at] = length;
      }

      return lengths;
    }

    if (encoding != encodingRle) {
      throw TcbException(
          "$fieldName: encoding $encoding cannot carry an array column's row lengths");
    }

    var filled = 0;

    while (filled < rowCount) {
      final run = reader.readCounter32();
      final value = reader.readOptimalInt32();

      if (run < 1 || run > rowCount - filled) {
        throw TcbException(
            '$fieldName: a run of $run lengths cannot cover the ${rowCount - filled} '
            'rows left in the column');
      }

      if (value < 0) {
        throw TcbException('$fieldName: a row declares $value elements');
      }

      for (var at = 0; at < run; at++) {
        lengths[filled++] = value;
      }
    }

    return lengths;
  }

  /// A dictionary whose entries are lists of references into a table of the pieces they
  /// are built from.
  ///
  /// Two reads and a concatenation: the table, which is front coded because its own
  /// entries share their fronts, and then each value as the pieces it is made of. The
  /// result is the same list of whole strings every other dictionary produces, so nothing
  /// downstream of here knows which kind it came from.
  static List<String> _readSegmentDictionary(TcbReader reader, String fieldName) {
    final segmentCount = reader.readCounter32();

    if (segmentCount < 0) {
      throw TcbException('$fieldName: the segment count is negative');
    }

    if (segmentCount > reader.remaining) {
      throw TcbException(
          '$fieldName: a segment table of $segmentCount entries is larger than the file '
          'can hold');
    }

    final segments = List<Uint8List>.filled(segmentCount, Uint8List(0));
    var previousLength = 0;

    for (var at = 0; at < segmentCount; at++) {
      final shared = reader.readCounter32();
      final rest = reader.readCounter32();

      if (shared < 0 || rest < 0 || shared > previousLength) {
        throw TcbException(
            '$fieldName: segment $at shares $shared bytes with an entry of '
            '$previousLength');
      }

      final segment = Uint8List(shared + rest);

      if (shared > 0) segment.setRange(0, shared, segments[at - 1]);
      if (rest > 0) reader.readBytesInto(segment, shared, rest);

      segments[at] = segment;
      previousLength = segment.length;
    }

    final count = reader.readCounter32();

    if (count < 0) {
      throw TcbException('$fieldName: the dictionary entry count is negative');
    }

    if (count > reader.remaining) {
      throw TcbException(
          '$fieldName: a dictionary of $count entries is larger than the file can hold');
    }

    final entries = List<String>.filled(count, '');
    var scratch = Uint8List(64);

    for (var at = 0; at < count; at++) {
      final pieces = reader.readCounter32();

      if (pieces < 0) {
        throw TcbException('$fieldName: dictionary entry $at declares $pieces pieces');
      }

      var length = 0;

      for (var piece = 0; piece < pieces; piece++) {
        final index = reader.readCounter32();

        if (index < 0 || index >= segmentCount) {
          throw TcbException(
              '$fieldName: segment index $index is out of range - the table holds '
              '$segmentCount entries');
        }

        final segment = segments[index];

        if (length + segment.length > scratch.length) {
          var capacity = scratch.length;

          while (capacity < length + segment.length) {
            capacity *= 2;
          }

          final grown = Uint8List(capacity);
          grown.setRange(0, length, scratch);
          scratch = grown;
        }

        scratch.setRange(length, length + segment.length, segment);
        length += segment.length;
      }

      entries[at] =
          length == 0 ? '' : utf8.decode(Uint8List.sublistView(scratch, 0, length));
    }

    return entries;
  }

  /// Up to [limit] rows that all hold the next value, as `(n, value)`. The count is
  /// always at least 1.
  ///
  /// This is what makes a run cost one call instead of one per row: the generated loop
  /// asks once, then assigns the value that many times. An encoding that cannot promise
  /// sameness cheaply answers 1, so the caller's loop is correct over every encoding and
  /// only faster over runs.
  (int, int) nextSameI32(int limit) {
    if (_encoding == encodingRle) {
      _rowsRemaining--;
      if (_runRemaining == 0) _readRun();

      final n = _runRemaining < limit ? _runRemaining : limit;
      _runRemaining -= n;
      _rowsRemaining -= n - 1;

      return (n, _runValue);
    }

    if (_encoding == encodingDeltaRle && _started) {
      _rowsRemaining--;
      if (_runRemaining == 0) _readRun();

      if (_runValue == 0) {
        // A zero-delta run is a run of one value.
        final n = _runRemaining < limit ? _runRemaining : limit;
        _runRemaining -= n;
        _rowsRemaining -= n - 1;

        return (n, _previous);
      }

      _runRemaining--;
      _previous = _wrap32(_previous + _runValue);

      return (1, _previous);
    }

    return (1, nextI32());
  }

  /// The string counterpart of [nextSameI32].
  (int, String) nextSameString(int limit) {
    if (_encoding == encodingDictRle || _encoding == encodingDictFrontRle) {
      _rowsRemaining--;
      if (_runRemaining == 0) _readRun();

      final n = _runRemaining < limit ? _runRemaining : limit;
      _runRemaining -= n;
      _rowsRemaining -= n - 1;

      return (n, _dictionaryEntry(_runValue));
    }

    return (1, nextString());
  }

  void _readRun() {
    final length = _reader.readCounter32();

    // + 1 because the row this run was read for is already counted out of
    // _rowsRemaining by its next call.
    if (length < 1 || length > _rowsRemaining + 1) {
      throw TcbException(
          '$_fieldName: a run of $length values cannot cover the '
          '${_rowsRemaining + 1} rows left in the column');
    }

    _runRemaining = length;
    _runValue = _reader.readOptimalInt32();
  }

  String _dictionaryEntry(int index) {
    final dictionary = _dictionary!;

    if (index < 0 || index >= dictionary.length) {
      throw TcbException(
          '$_fieldName: dictionary index $index is out of range - the '
          'dictionary holds ${dictionary.length} entries');
    }

    return dictionary[index];
  }

  /// The delta family's 32-bit wrap. Dart's int is wider than the format's (64 bits
  /// on the VM, 53 on the web), so the wrap is explicit: the low 32 bits of the sum,
  /// sign-extended. The mask is 32-bit on the web too - here that truncation is the
  /// point - while the sign extension is arithmetic, for the same reason
  /// readOptimalInt32 divides rather than shifts.
  static int _wrap32(int value) {
    value &= 0xFFFFFFFF;
    return value >= 0x80000000 ? value - 0x100000000 : value;
  }
}

/// A file's plaintext bytes, checked against its MAC on the way.
///
/// Call this on the bytes before handing them to a reader. A file that is neither encrypted
/// nor authenticated comes back untouched, so the call belongs in the load path whether or
/// not the project uses either.
///
/// The order is verify, then decrypt. The tag covers the file as it is stored, so an altered
/// file is refused before the key is used on it, and the header - the flags, the cipher
/// byte, the nonce - is covered along with the body.
///
/// Decryption happens in place, and what comes back is a window onto the same list rather
/// than a copy of it. The fields this consumes are returned to what a plain file has in
/// them, so calling it twice on the same list is the same as calling it once.
///
/// What the two layers are and are not for: both keys ship inside the client that reads the
/// file. Encryption stops a data file being read in an editor; the MAC stops an edited one
/// loading. Neither stops anyone who can take the keys out of the client, and no format
/// does.
///
/// [macKey] is the key the files were signed with, or null when the project does not use
/// one. A reader that has one refuses a file that carries no MAC: the field being zero is
/// how a file says it is unauthenticated, so accepting that from a project that signs its
/// files would put the check sixteen zero bytes away from being removed.
///
/// [verifyMac] false skips the check. For tools and for measuring load time - and no weaker
/// than it looks, because anyone who can flip this flag in a shipped binary can read the key
/// out of the same binary.
Uint8List open(Uint8List data, List<int>? key,
    [List<int>? macKey, bool verifyMac = true]) {
  if (data.length < headerSize) throw TcbException('the file is too short to be a table');

  if (_readMagic(data, magicOffset) != magic) {
    throw TcbException('the file does not begin with the table file signature');
  }

  if (verifyMac) _checkMac(data, macKey);

  if (data[flagsOffset] & flagEncrypted == 0) return data;

  if (data[cipherOffset] != cipherChaCha20) {
    throw TcbException(
        'the file uses cipher ${data[cipherOffset]}, which this reader does not know');
  }

  if (key == null || key.length != 32) {
    throw TcbException(
        'the file is encrypted and no key, or a key that is not 32 bytes, was given');
  }

  _chaCha20Apply(key, data, nonceOffset, keyCheckOffset);

  if (_readMagic(data, keyCheckOffset) != magic) {
    throw TcbException(
        'the file did not decrypt to a table - the key is not the one it was written '
        'with');
  }

  // Back to what a plain file holds in these bytes, so that a second call over the same
  // list passes it through instead of decrypting it again.
  data[flagsOffset] &= ~flagEncrypted;
  data[cipherOffset] = cipherNone;

  for (var at = 0; at < nonceSize; at++) {
    data[nonceOffset + at] = 0;
  }

  return data;
}

/// Four bytes as the fixed32 the signature and the key check are compared as.
int _readMagic(Uint8List data, int at) =>
    data[at] | data[at + 1] << 8 | data[at + 2] << 16 | data[at + 3] << 24;

/// The MAC field against the file's own bytes, and against whether a key was given.
void _checkMac(Uint8List data, List<int>? macKey) {
  var present = false;

  for (var at = 0; at < macSize && !present; at++) {
    present = data[macOffset + at] != 0;
  }

  // Nothing to check with. A file that carries a tag is read anyway rather than refused:
  // this reader has no way to tell whether the tag is good, and a client built before the
  // project turned MACs on is one this format has promised can still read what it is sent.
  if (macKey == null) return;

  if (macKey.length != 32) throw TcbException('the MAC key given is not 32 bytes');

  if (!present) {
    throw TcbException(
        'the file carries no MAC and this build expects one - it was exported without a '
        'MAC key, or the field was cleared after it was written');
  }

  if (!_verifyTag(data, macKey)) {
    throw TcbException(
        'the file does not match its MAC - it was altered after it was exported, or it '
        'was signed with a different key');
  }
}

/// Reads and checks a table file's header, returning the row count that follows it.
///
/// Every flag means the file needs handling this build does not have, the encrypted one
/// included. [open] clears that bit on the plaintext it hands back, so a reader that still
/// sees it was given the ciphertext without the key - and naming that is worth more than
/// letting the block lengths make what they can of the bytes.
Header readTableHeader(TcbReader reader) {
  // Checked again here rather than only in open, because a reader can be handed bytes that
  // never went through it.
  if (reader.readUint32() != magic) {
    throw TcbException('the file does not begin with the table file signature');
  }

  final version = reader.readUint32();

  if (version != formatVersion) {
    throw TcbException(
        'table format version $version is not supported (expected $formatVersion)');
  }

  final flags = reader.readUint8();

  if (flags & flagEncrypted != 0) {
    throw TcbException(
        'the table is encrypted and was not decrypted - pass the key through open first');
  }

  if (flags != 0) {
    throw TcbException('table declares unsupported features');
  }

  // The cipher byte, the nonce, the MAC and the key check. open has dealt with all four by
  // now; what is left is to be standing at the body.
  reader.skip(headerSize - cipherOffset);

  final count = reader.readCounter32();
  if (count < 0) throw TcbException('table row count is negative');

  final columnCount = reader.readCounter32();
  if (columnCount < 0) throw TcbException('table column count is negative');

  final columns = <Column>[];

  for (var at = 0; at < columnCount; at++) {
    final tag = reader.readCounter32();
    final wire = reader.readUint8();
    final encoding = reader.readUint8();
    final byteLength = reader.readUint32();
    columns.add(
        Column(tag, wire & 0x0f, (wire >> 4) & 0x03, encoding, byteLength,
            (wire & 0x40) != 0, (wire & 0x80) != 0));
  }

  // What the descriptors say about the file, checked before anybody allocates for the
  // row count. The blocks are all that follows the header, so their declared lengths have
  // to add up to the bytes left. A raw block also costs at least one byte per row - a
  // varint's shortest form, an empty string's length prefix, a variable array's counter -
  // so a larger row count is one the exporter could not have written. An encoded block
  // has no such floor; its decode checks run sums and dictionary bounds instead.

  final available = reader.remaining;
  var declared = 0;

  for (final column in columns) {
    if (column.byteLength < 0 || column.byteLength > available - declared) {
      throw TcbException(
          'column tag ${column.tag} declares ${column.byteLength} bytes, which the file '
          'cannot hold');
    }

    declared += column.byteLength;

    if (column.encoding == encodingRaw && count > column.byteLength) {
      throw TcbException(
          'the row count $count is larger than column tag ${column.tag} can hold in its '
          '${column.byteLength} bytes');
    }

  }

  if (declared != available) {
    throw TcbException(
        'the columns declare $declared bytes but $available follow the header');
  }

  return Header(count, columns);
}

/// A nullable column's presence bitmap, which sits at the front of its block.
///
/// Empty for a column that is not optional, which is what lets the generated code call
/// [isPresent] without testing first.
List<int> readPresence(TcbReader reader, Column column, int rowCount) {
  if (!column.nullable) {
    return const <int>[];
  }

  // The bitmap is a bit-packed boolean column of width one, so it carries an encoding
  // byte and is laid out by the same choice a packed value block uses. Its width and base
  // are known in advance, which is why it does not carry them.
  final encoding = reader.readUint8();

  return reader.readByteStream(encoding, (rowCount + 7) ~/ 8, 'a presence bitmap');
}

/// A column's element bitmap, behind the row bitmap and in front of the values.
///
/// Empty for a column that does not carry one. Its length is written ahead of it as a
/// counter32, because a variable-length column's total is the sum of its row lengths and
/// those live inside the value block - a reader meeting the bitmap first would have nothing
/// to size it by. spec/nullable-array-elements.md.
List<int> readElementPresence(TcbReader reader, Column column) {
  if (!column.elementNullable) {
    return const <int>[];
  }

  final elements = reader.readCounter32();
  final encoding = reader.readUint8();

  return reader.readByteStream(
      encoding, (elements + 7) ~/ 8, 'an element presence bitmap');
}

/// Whether a row has a value, for a column that says which do.
///
/// An empty bitmap means the column is not optional, and then every row has one.
bool isPresent(List<int> presence, int row) =>
    presence.isEmpty || (presence[row >> 3] & (1 << (row & 7))) != 0;

/// That a column is what the generated member expects, or a lossless promotion of it.
/// Refusal is by name and both types, never by reading anyway.
void checkColumn(Column column, String fieldName, int kind, bool nullable,
    List<int> accepted, [bool elementNullable = false]) {
  // The same statement about the other bitmap: code not expecting one would read it as
  // values. spec/nullable-array-elements.md.
  if (column.elementNullable != elementNullable) {
    throw TcbException(
        "$fieldName: the file and the generated member disagree about whether this column's "
        'elements are optional. The schema changed; regenerate the code or rebuild the data.');
  }

  // Nullability is part of the shape: a file that says optional puts a presence bitmap in
  // front of the block, and code not expecting one would read the bitmap as values. So
  // adding or removing a `?` is a schema change like any other, caught here rather than in
  // whatever the misread bytes happened to mean.
  if (column.nullable != nullable) {
    throw TcbException(
        '$fieldName: the file and the generated member disagree about whether this column '
        'is optional. The schema changed; regenerate the code or rebuild the data.');
  }

  // A negative count says the member claims no length: how many elements a row holds is
  // what the file states. The kind is still the member's claim.
  // spec/nullable-array-elements.md.
  if (column.kind != kind) {
    throw TcbException(
        '$fieldName: the file column (kind ${column.kind}) does not match the '
        'generated member (kind $kind). The schema changed shape; '
        'regenerate the code or rebuild the data.');
  }

  // An encoding this build cannot decode - or one the spec does not define for this
  // element - is refused by name, exactly like an element it cannot read. An unknown
  // column's encoding never gets here - a skip is a skip whatever the block's layout.
  if (!_encodingSupported(column)) {
    throw TcbException(
        "$fieldName: the file's column uses encoding ${column.encoding}, which this "
        'reader cannot decode for its element type. Regenerate the code or rebuild '
        'the data.');
  }

  if (!accepted.contains(column.element)) {
    throw TcbException(
        '$fieldName: the file carries element type ${column.element}, which this member '
        'cannot read (accepts $accepted). The column changed type incompatibly; regenerate '
        'the code or rebuild the data.');
  }
}

/// The (element, encoding) pairs the spec defines. Integers take the integer encodings,
/// strings the dictionary ones, and an array takes the composition that applies all of
/// those to its elements.
bool _encodingSupported(Column column) {
  if (column.encoding == encodingRaw) return true;

  // An array's block says what its elements use, and the element encoding is checked as it
  // is read rather than here - the descriptor carries only the outer one, so this is as far
  // as the descriptor can be checked.
  if (column.kind != kindScalar) return column.encoding == encodingArray;

  switch (column.element) {
    case elementBool:
    case elementVarint:
      return column.encoding == encodingRle || column.encoding == encodingBitpack;

    case elementI32:
      return (column.encoding >= encodingVarint &&
              column.encoding <= encodingDeltaRle) ||
          column.encoding == encodingBitpack;

    // The dictionary is parameterized by element, so this reaches it with entries that are
    // simply their own raw bytes.
    case elementI64:
      return column.encoding == encodingDict ||
          column.encoding == encodingDictRle ||
          column.encoding == encodingBitpack;

    // A float column additionally reaches the integer encodings, through the block that
    // says its values are whole numbers.
    case elementF32:
    case elementF64:
      return column.encoding == encodingDict ||
          column.encoding == encodingDictRle ||
          column.encoding == encodingWhole;

    // And a string dictionary can be front coded or built from segments, both of which are
    // meaningless for a fixed-width element and refused for one.
    case elementString:
      return (column.encoding >= encodingDict &&
              column.encoding <= encodingDictFrontRle) ||
          column.encoding == encodingDictSegment ||
          column.encoding == encodingDictSegmentRle;

    default:
      return false;
  }
}

/// That a block was consumed exactly: a mismatch is a format disagreement, and stopping
/// here names the column instead of corrupting the next.
void checkBlockEnd(TcbReader reader, Column column, int expectedEnd) {
  if (reader.position != expectedEnd) {
    throw TcbException(
        'column tag ${column.tag}: its block declared ${column.byteLength} bytes but the '
        'read ended ${expectedEnd - reader.position} bytes short of its boundary');
  }
}

/// Reads a whole file into memory.
Uint8List readAllBytes(String filename) => File(filename).readAsBytesSync();

// HMAC-SHA-256 over the file, truncated to the sixteen bytes the header keeps for it.
//
// Written out here for the same reason the cipher below is: SHA-256 lives in the `crypto`
// package, which is a dependency this runtime does not have and does not want. What it costs
// is the two hundred lines below.
//
// What the tag catches is what the structural checks cannot. A block length that does not
// add up is a malformed file and the reader says so; four other bytes in an f32 column is a
// well-formed file holding a different number, and no check over a file's shape can tell
// that from data that was always there.

/// Whether the file's MAC field is the tag its own bytes produce under this key.
bool _verifyTag(Uint8List data, List<int> key) {
  final expected = _hmacSha256(key, data);

  // Every byte, always: a comparison that returns early tells the caller how far it got.
  var difference = 0;

  for (var at = 0; at < macSize; at++) {
    difference |= expected[at] ^ data[macOffset + at];
  }

  return difference == 0;
}

/// The tag for a file: HMAC-SHA-256 over every byte but the sixteen the tag lives in.
///
/// Skipping them is the same as zeroing them and cheaper by a copy of the file.
Uint8List _hmacSha256(List<int> key, Uint8List data) {
  final block = Uint8List(64);

  // A key longer than the block is hashed first; ours is thirty-two bytes, but the rule is
  // part of HMAC and leaving it out would make this agree with nothing.
  if (key.length > 64) {
    block.setRange(0, 32, _sha256([Uint8List.fromList(key)]));
  } else {
    block.setRange(0, key.length, key);
  }

  final inner = Uint8List(64);
  final outer = Uint8List(64);

  for (var at = 0; at < 64; at++) {
    inner[at] = block[at] ^ 0x36;
    outer[at] = block[at] ^ 0x5c;
  }

  final innerDigest = _sha256([
    inner,
    Uint8List.sublistView(data, 0, macOffset),
    Uint8List.sublistView(data, keyCheckOffset),
  ]);

  return _sha256([outer, innerDigest]);
}

/// The round constants: the fractional parts of the cube roots of the first 64 primes.
final Uint32List _sha256K = Uint32List.fromList(const [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4,
  0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
  0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
  0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
  0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
  0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
  0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116,
  0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
  0xc67178f2,
]);

/// SHA-256 of the pieces, hashed as though they were one message.
///
/// Pieces rather than one list because every call here has more than one and none of them
/// wants the copy that joining would cost: HMAC hashes a pad followed by the message, and
/// the message itself is the file with a hole in the middle of it.
Uint8List _sha256(List<Uint8List> pieces) {
  final state = Uint32List.fromList(const [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
  ]);

  final schedule = Uint32List(64);
  final block = Uint8List(64);

  var filled = 0;
  var length = 0;

  for (final piece in pieces) {
    length += piece.length;

    var at = 0;

    // The partial block first, then whole blocks straight out of the piece: the copy into
    // [block] is only for the bytes that straddle a boundary.
    while (at < piece.length) {
      if (filled == 0 && piece.length - at >= 64) {
        _sha256Block(state, schedule, piece, at);
        at += 64;
        continue;
      }

      final taking =
          (64 - filled) < (piece.length - at) ? 64 - filled : piece.length - at;

      block.setRange(filled, filled + taking, piece, at);

      filled += taking;
      at += taking;

      if (filled == 64) {
        _sha256Block(state, schedule, block, 0);
        filled = 0;
      }
    }
  }

  // The padding: a set bit, zeros, and the message length in bits as a 64-bit big-endian
  // number. Two blocks when the length does not fit in the one that is open.
  final tail = Uint8List(filled + 9 > 64 ? 128 : 64);
  tail.setRange(0, filled, block);
  tail[filled] = 0x80;

  final bits = length * 8;

  // Split rather than shifted: on the web a Dart int is a double, and a shift past 32 bits
  // is where that stops behaving like an integer.
  final high = bits ~/ 0x100000000;

  tail[tail.length - 8] = (high >> 24) & 0xff;
  tail[tail.length - 7] = (high >> 16) & 0xff;
  tail[tail.length - 6] = (high >> 8) & 0xff;
  tail[tail.length - 5] = high & 0xff;
  tail[tail.length - 4] = (bits >> 24) & 0xff;
  tail[tail.length - 3] = (bits >> 16) & 0xff;
  tail[tail.length - 2] = (bits >> 8) & 0xff;
  tail[tail.length - 1] = bits & 0xff;

  for (var at = 0; at < tail.length; at += 64) {
    _sha256Block(state, schedule, tail, at);
  }

  final digest = Uint8List(32);

  for (var at = 0; at < 8; at++) {
    digest[at * 4] = (state[at] >> 24) & 0xff;
    digest[at * 4 + 1] = (state[at] >> 16) & 0xff;
    digest[at * 4 + 2] = (state[at] >> 8) & 0xff;
    digest[at * 4 + 3] = state[at] & 0xff;
  }

  return digest;
}

/// One 64-byte block of the compression function.
void _sha256Block(
    Uint32List state, Uint32List schedule, Uint8List data, int offset) {
  for (var at = 0; at < 16; at++) {
    schedule[at] = data[offset + at * 4] << 24 |
        data[offset + at * 4 + 1] << 16 |
        data[offset + at * 4 + 2] << 8 |
        data[offset + at * 4 + 3];
  }

  for (var at = 16; at < 64; at++) {
    final before = schedule[at - 15];
    final near = schedule[at - 2];

    final s0 = _rotateRight(before, 7) ^ _rotateRight(before, 18) ^ (before >> 3);
    final s1 = _rotateRight(near, 17) ^ _rotateRight(near, 19) ^ (near >> 10);

    schedule[at] = schedule[at - 16] + s0 + schedule[at - 7] + s1;
  }

  var a = state[0], b = state[1], c = state[2], d = state[3];
  var e = state[4], f = state[5], g = state[6], h = state[7];

  for (var at = 0; at < 64; at++) {
    final s1 = _rotateRight(e, 6) ^ _rotateRight(e, 11) ^ _rotateRight(e, 25);
    final choice = (e & f) ^ (~e & g);
    final one = (h + s1 + choice + _sha256K[at] + schedule[at]) & 0xffffffff;

    final s0 = _rotateRight(a, 2) ^ _rotateRight(a, 13) ^ _rotateRight(a, 22);
    final majority = (a & b) ^ (a & c) ^ (b & c);
    final two = (s0 + majority) & 0xffffffff;

    h = g;
    g = f;
    f = e;
    e = (d + one) & 0xffffffff;
    d = c;
    c = b;
    b = a;
    a = (one + two) & 0xffffffff;
  }

  state[0] += a;
  state[1] += b;
  state[2] += c;
  state[3] += d;
  state[4] += e;
  state[5] += f;
  state[6] += g;
  state[7] += h;
}

int _rotateRight(int value, int count) =>
    ((value >> count) | (value << (32 - count))) & 0xffffffff;

// The ChaCha20 stream cipher of RFC 8439, as the file envelope uses it.
//
// Written out here rather than taken from a package because this runtime has no
// dependencies and keeps none, and because what the format wants is a plain keystream
// rather than an authenticated construction: applying it leaves every byte count as it
// was, so the structural checks - the block lengths that must sum exactly - hold over the
// ciphertext unchanged.
//
// The state words live in a Uint32List, so every addition wraps where it is stored at the
// 32 bits the cipher is defined over rather than at whatever a Dart int is - 64 bits on
// the VM, and a double on the web.

/// Exclusive-ors the keystream over [data] from [from] to its end, in place.
///
/// One routine for both directions, which is what a stream cipher is: the keystream
/// depends only on the key, the nonce and the position, so applying it twice returns what
/// went in. The block counter starts at zero, and the nonce is the twelve bytes of [data]
/// at [nonceAt].
void _chaCha20Apply(List<int> key, Uint8List data, int nonceAt, int from) {
  final state = Uint32List(16);
  final working = Uint32List(16);
  final keystream = Uint8List(64);
  final keystreamWords = ByteData.view(keystream.buffer);

  // "expand 32-byte k", as four little-endian words.
  state[0] = 0x61707865;
  state[1] = 0x3320646e;
  state[2] = 0x79622d32;
  state[3] = 0x6b206574;

  for (var at = 0; at < 8; at++) {
    state[4 + at] = _littleEndianWord(key, at * 4);
  }

  state[12] = 0;

  for (var at = 0; at < 3; at++) {
    state[13 + at] = _littleEndianWord(data, nonceAt + at * 4);
  }

  for (var offset = from; offset < data.length; offset += 64) {
    _chaCha20Block(state, working, keystreamWords);

    final count = data.length - offset < 64 ? data.length - offset : 64;

    for (var at = 0; at < count; at++) {
      data[offset + at] ^= keystream[at];
    }

    state[12]++;
  }
}

/// One 64-byte keystream block: twenty rounds over a copy of the state.
void _chaCha20Block(Uint32List state, Uint32List working, ByteData keystream) {
  working.setAll(0, state);

  // Ten double rounds. Each is four column quarter-rounds and four diagonal ones, which
  // between them let every word reach every other.
  for (var round = 0; round < 10; round++) {
    _chaCha20QuarterRound(working, 0, 4, 8, 12);
    _chaCha20QuarterRound(working, 1, 5, 9, 13);
    _chaCha20QuarterRound(working, 2, 6, 10, 14);
    _chaCha20QuarterRound(working, 3, 7, 11, 15);

    _chaCha20QuarterRound(working, 0, 5, 10, 15);
    _chaCha20QuarterRound(working, 1, 6, 11, 12);
    _chaCha20QuarterRound(working, 2, 7, 8, 13);
    _chaCha20QuarterRound(working, 3, 4, 9, 14);
  }

  // Added back to the state it started from, which is what stops the rounds being
  // reversible and so the keystream being recoverable.
  for (var at = 0; at < 16; at++) {
    working[at] += state[at];
    keystream.setUint32(at * 4, working[at], Endian.little);
  }
}

void _chaCha20QuarterRound(Uint32List block, int a, int b, int c, int d) {
  block[a] += block[b];
  block[d] = _rotateLeft32(block[d] ^ block[a], 16);
  block[c] += block[d];
  block[b] = _rotateLeft32(block[b] ^ block[c], 12);
  block[a] += block[b];
  block[d] = _rotateLeft32(block[d] ^ block[a], 8);
  block[c] += block[d];
  block[b] = _rotateLeft32(block[b] ^ block[c], 7);
}

/// A 32-bit left rotation.
///
/// Multiplied and divided rather than shifted, for the reason readOptimalInt32 divides: a
/// shift is a signed 32-bit operation on the web and these words reach 2^32. The two parts
/// share no bit, so adding them is the or.
int _rotateLeft32(int value, int count) =>
    (value * _powersOfTwo[count]) % 0x100000000 + value ~/ _powersOfTwo[32 - count];

/// Four bytes as a little-endian word, built with arithmetic for the same reason.
int _littleEndianWord(List<int> bytes, int at) =>
    bytes[at] + bytes[at + 1] * 256 + bytes[at + 2] * 65536 + bytes[at + 3] * 16777216;

/// Two to the index, up to 2^32 - each of them a value a double holds exactly.
const List<int> _powersOfTwo = [
  1, 2, 4, 8, 16, 32, 64, 128,
  256, 512, 1024, 2048, 4096, 8192, 16384, 32768,
  65536, 131072, 262144, 524288, 1048576, 2097152, 4194304, 8388608,
  16777216, 33554432, 67108864, 134217728, 268435456, 536870912, 1073741824,
  2147483648, 4294967296,
];
